import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  
  const basePrice = parseFloat(input?.standard_pricing?.price ?? 0);
  const measuredPower = parseFloat(input?.tsl_wo_work_order_attribute?.measured_power?.power);

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Demanda not found"
      }
    }
  }

  let total_amount = basePrice * measuredPower;

 if (total_amount) {
    const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);
    billingItem.billing_item_amount = total_amount;

    return {
      ...input,
      result: {
          total_amount: total_amount,
          status: "OK",
          status_description: "Demanda calculation rule completed"
        }
    };
  } else {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "The amount of the demanda rule could not be calculated."
      }
    };
  }
};
